module Tests.FSharp.GeneratedCode

open System.Data.SqlTypes
open System.Linq

open LinqToDB
open LinqToDB.Data

open NUnit.Framework

open Tests.FSharp.Scaffold
// generated extension members (Find, procedures) are visible only through their namespace
open Tests.FSharp.Scaffold.SQLite
open Tests.FSharp.Scaffold.SQLiteFluent
open Tests.FSharp.Scaffold.SqlServer

// Runtime tests over the committed CLI scaffolder F# output (Tests/FSharp.Scaffold, #1553), compiled into this
// project. The goldens are regenerated by generate.ps1, not by CI (see #6021).

let TestGeneratedQueries (db : DataConnection) =
    use ctx = new SQLite.TestDataDB(new DataOptions<SQLite.TestDataDB>(db.Options))

    let people = ctx.People.ToList()
    Assert.That(people.Exists(fun p -> p.MiddleName.IsSome), Is.True)
    Assert.That(people.Exists(fun p -> p.MiddleName.IsNone), Is.True)

    let doctor = ctx.Doctors.First()
    Assert.That(isNull (box doctor.FkDoctor0), Is.True)

    let loaded = ctx.Doctors.LoadWith(fun d -> d.FkDoctor0).First(fun d -> d.PersonId = doctor.PersonId)
    Assert.That(loaded.FkDoctor0.PersonId, Is.EqualTo doctor.PersonId)

    Assert.That((nonNull (ctx.People.Find(doctor.PersonId))).PersonId, Is.EqualTo doctor.PersonId)
    Assert.That(isNull (ctx.People.Find(-1L)), Is.True)
    Assert.That((nonNull (ctx.FindPersonAsync(doctor.PersonId).Result)).PersonId, Is.EqualTo doctor.PersonId)

    // equatable entities (--equatable-entities) compare by primary key only
    let person = nonNull (ctx.People.Find(doctor.PersonId))
    Assert.That(loaded, Is.EqualTo doctor)
    Assert.That({ person with FirstName = person.FirstName + "!" }, Is.EqualTo person)
    Assert.That(people.Find(fun p -> p.PersonId <> person.PersonId), Is.Not.EqualTo person)
    Assert.That(people.Concat(ctx.People.ToList()).Distinct().Count(), Is.EqualTo people.Count)

let TestGeneratedFluentMapping (db : DataConnection) =
    use ctx = new SQLiteFluent.TestDataDB(new DataOptions<SQLiteFluent.TestDataDB>(db.Options))

    // association mapping only exists in the fluent static initializer (records carry no attributes)
    let doctor = ctx.Doctors.LoadWith(fun d -> d.FkDoctor0).First()
    Assert.That(doctor.FkDoctor0.PersonId, Is.EqualTo doctor.PersonId)
    Assert.That((nonNull (ctx.People.Find(doctor.PersonId))).PersonId, Is.EqualTo doctor.PersonId)

let TestGeneratedProcedureOptionParameters (db : DataConnection) =
    use ctx = new SqlServer.TestDataDB(new DataOptions<SqlServer.TestDataDB>(db.Options))

    let mutable output : SqlInt32 option = None
    let mutable ret    = 0

    ctx.ExecuteProcIntParameters(Some (SqlInt32 5), &output, &ret) |> ignore
    Assert.That(output, Is.EqualTo(Some (SqlInt32 6)))

    ctx.ExecuteProcIntParameters(None, &output, &ret) |> ignore
    Assert.That(output, Is.EqualTo None)
